        return float(min(budget, DAILY_SALARY * 0.25))

    slots = supply / float(WATER_REQ)
    many_slots = slots >= 2.0
    tight_supply = supply <= 17

    if eric_bid is None:
        eric_bid = 64.0
    if cindy_bid is None:
        cindy_bid = 108.0

