    if no_water >= 1:
        danger += 2
    if no_water >= 2:
        danger += 2
    if tight_supply:
        danger += 1
    if day >= 8:
        danger += 1

    if danger >= 4:
        target = max(eric_bid + 4.0, DAILY_SALARY * 0.95)
        if tight_supply:
            target = max(target, min(cindy_bid * 0.92, DAILY_SALARY * 1.45))
    elif danger >= 2:
        if many_slots:
            target = max(48.0, eric_bid - 6.0)
        else:
            target = max(58.0, eric_bid + 2.0)
    else:
        if many_slots:
            target = 34.0
        else:
            target = 52.0

